        .card-title {
            font-size: 14px;
            font-weight: bold;
            color: var(--accent-red);
            margin-bottom: 12px;
            padding-bottom: 8px;
            border-bottom: 1px solid var(--border-dark);
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .card-title::before {
            content: '✦';
            color: var(--border-gold);
        }

        /* ==================== 主角卡片布局 ==================== */
        .protagonist-card {
