            gap: 8px;
        }

        .inventory-item {
            aspect-ratio: 1;
            background: var(--parchment-light);
            border: 1px solid var(--border-dark);
            border-radius: 6px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.2s;
            padding: 5px;
            position: relative;
        }

        .inventory-item:hover {
            background: #fff;
            transform: scale(1.05);
            box-shadow: var(--shadow-light);
        }

        .inventory-item.equipable {
            border-color: var(--border-gold);
        }

        .inventory-item-icon {
            font-size: 24px;
        }

        .inventory-item-name {
            font-size: 9px;
            text-align: center;
            margin-top: 2px;
            color: var(--ink-secondary);
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
            width: 100%;
        }

        .inventory-item-count {
            position: absolute;
            bottom: 2px;
            right: 4px;
            font-size: 10px;
            font-weight: bold;
            color: var(--ink-primary);
        }

        /* 筛选标签 */
        .filter-tabs {
            display: flex;
            gap: 5px;
            margin-bottom: 12px;
            flex-wrap: wrap;
        }

        .filter-tab {
            padding: 5px 12px;
            border: 1px solid var(--border-dark);
            border-radius: 15px;
            background: var(--parchment-light);
            font-size: 11px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .filter-tab:hover,
        .filter-tab.active {
            background: var(--border-gold);
            color: #fff;
        }

        /* ==================== 技能列表 ==================== */
        .skill-list {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .skill-item {
            padding: 12px;
            background: var(--parchment-light);
            border: 1px solid var(--border-dark);
            border-radius: 8px;
            display: flex;
            gap: 12px;
            align-items: flex-start;
        }

        .skill-item-icon {
            font-size: 28px;
            flex-shrink: 0;
        }

        .skill-item-info {
            flex: 1;
        }

        .skill-item-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 4px;
        }

        .skill-item-name {
            font-size: 14px;
            font-weight: bold;
            color: var(--ink-primary);
        }

        .skill-item-level {
            font-size: 11px;
            color: var(--border-gold);
            font-weight: bold;
        }

        .skill-item-meta {
            font-size: 11px;
            color: var(--ink-light);
            margin-bottom: 4px;
        }

        .skill-item-desc {
            font-size: 11px;
            color: var(--ink-secondary);
        }

        .skill-item-proficiency {
            margin-top: 6px;
        }

        .proficiency-bar {
            height: 6px;
            background: rgba(0, 0, 0, 0.15);
            border-radius: 3px;
            overflow: hidden;
        }

        .proficiency-fill {
            height: 100%;
            background: linear-gradient(90deg, var(--border-gold), #ffd700);
            border-radius: 3px;
        }

        .proficiency-text {
            font-size: 9px;
            color: var(--ink-light);
            margin-top: 2px;
            text-align: right;
        }

        /* ==================== 角色详情 ==================== */
        .character-detail-header {
            display: flex;
            gap: 15px;
            margin-bottom: 15px;
        }

        .character-detail-avatar {
            width: 80px;
            height: 80px;
            border-radius: 50%;
            background: linear-gradient(135deg, #667eea, #764ba2);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 32px;
            color: #fff;
            flex-shrink: 0;
        }

        .character-detail-info {
            flex: 1;
        }

        .character-detail-name {
            font-size: 20px;
            font-weight: bold;
            color: var(--ink-primary);
            margin-bottom: 4px;
        }

        .character-detail-meta {
            font-size: 12px;
            color: var(--ink-light);
            margin-bottom: 10px;
        }

        .character-detail-resources {
            display: flex;
            flex-direction: column;
            gap: 5px;
        }

        .character-attributes {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 8px;
            margin-bottom: 15px;
        }

        .attribute-item {
            display: flex;
            justify-content: space-between;
            padding: 6px 10px;
            background: var(--parchment-light);
            border-radius: 4px;
            font-size: 12px;
        }

        .attribute-name {
            color: var(--ink-light);
        }

        .attribute-value {
            font-weight: bold;
            color: var(--ink-primary);
        }

        .character-info-section {
            margin-bottom: 15px;
            padding: 10px;
            background: rgba(0,0,0,0.03);
            border-radius: 8px;
        }

        .info-row {
            display: flex;
            margin-bottom: 8px;
            font-size: 12px;
        }

        .info-row:last-child {
            margin-bottom: 0;
        }

        .info-label {
            width: 70px;
            flex-shrink: 0;
            color: var(--ink-light);
        }

        .info-value {
            flex: 1;
            color: var(--ink-primary);
        }

        .character-skills {
            margin-bottom: 15px;
        }

        .character-skills-title {
            font-size: 12px;
            font-weight: bold;
            color: var(--ink-secondary);
            margin-bottom: 8px;
        }

        .character-skill-tag {
            display: inline-block;
            padding: 4px 10px;
            background: var(--parchment-light);
            border: 1px solid var(--border-dark);
            border-radius: 12px;
            font-size: 11px;
            margin-right: 5px;
            margin-bottom: 5px;
        }

        .interaction-buttons {
            display: flex;
            gap: 8px;
            flex-wrap: wrap;
        }

        .interaction-btn {
            padding: 8px 16px;
            border: 2px solid var(--border-dark);
            border-radius: 6px;
            background: var(--parchment-light);
            font-size: 12px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .interaction-btn:hover {
            background: var(--border-gold);
            color: #fff;
        }

        /* ==================== 加点弹窗 ==================== */
        .point-allocation {
            margin-bottom: 15px;
        }

        .allocation-row {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 8px 0;
            border-bottom: 1px solid var(--parchment-dark);
        }

        .allocation-name {
            font-size: 13px;
            width: 50px;
        }

        .allocation-current {
            font-size: 16px;
            font-weight: bold;
            width: 30px;
            text-align: center;
        }

        .allocation-controls {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .allocation-btn {
            width: 28px;
            height: 28px;
            border: 2px solid var(--border-dark);
            border-radius: 50%;
            background: var(--parchment-light);
            font-size: 16px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .allocation-btn:hover:not(:disabled) {
            background: var(--border-gold);
            color: #fff;
        }

        .allocation-btn:disabled {
            opacity: 0.3;
            cursor: not-allowed;
        }

        .allocation-change {
            font-size: 13px;
            min-width: 40px;
            text-align: center;
        }

        .allocation-change.positive { color: var(--success); }
        .allocation-change.negative { color: var(--danger); }

        .free-points-display {
            text-align: center;
            padding: 10px;
            background: rgba(184, 134, 11, 0.1);
            border-radius: 8px;
            margin-bottom: 15px;
        }

        .free-points-value {
            font-size: 28px;
            font-weight: bold;
            color: var(--border-gold);
        }

        .free-points-label {
            font-size: 11px;
            color: var(--ink-light);
        }

        .preview-section {
            background: rgba(0, 0, 0, 0.05);
            border-radius: 8px;
            padding: 12px;
            margin-top: 15px;
        }

        .preview-title {
            font-size: 11px;
            color: var(--ink-light);
            margin-bottom: 8px;
        }

        .preview-items {
            display: flex;
            justify-content: space-around;
        }

        .preview-item {
            text-align: center;
        }

        .preview-label {
            font-size: 10px;
            color: var(--ink-light);
        }

        .preview-values {
            font-size: 13px;
        }

        .preview-old {
            color: var(--ink-light);
            text-decoration: line-through;
        }

        .preview-new {
            color: var(--success);
            font-weight: bold;
        }

        .modal-buttons {
            display: flex;
            gap: 10px;
            margin-top: 15px;
        }

        .modal-btn {
            flex: 1;
            padding: 12px;
            border: 2px solid var(--border-dark);
            border-radius: 8px;
            font-size: 13px;
            font-weight: bold;
            cursor: pointer;
            transition: all 0.2s;
        }

        .modal-btn.primary {
            background: var(--border-gold);
            color: #fff;
        }

        .modal-btn.primary:hover {
            background: var(--accent-red);
        }

        .modal-btn.secondary {
            background: var(--parchment-light);
            color: var(--ink-primary);
        }

        .modal-btn.secondary:hover {
            background: var(--parchment-dark);
        }

        /* ==================== 目标选择 ==================== */
        .target-list {
            display: flex;
            flex-direction: column;
            gap: 8px;
            max-height: 300px;
            overflow-y: auto;
        }

        .target-item {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 12px;
            background: var(--parchment-light);
            border: 2px solid transparent;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .target-item:hover {
            background: #fff;
        }

        .target-item.selected {
            border-color: var(--accent-red);
            background: rgba(139, 0, 0, 0.1);
        }

        .target-avatar {
            width: 45px;
            height: 45px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 20px;
            color: #fff;
        }

        .target-item.ally .target-avatar {
            background: linear-gradient(135deg, #2ecc71, #27ae60);
        }

        .target-item.enemy .target-avatar {
            background: linear-gradient(135deg, #e74c3c, #c0392b);
        }

        .target-info {
            flex: 1;
        }

        .target-name {
            font-size: 14px;
            font-weight: bold;
            margin-bottom: 4px;
        }

        .target-status {
            display: flex;
            gap: 10px;
            font-size: 11px;
            color: var(--ink-light);
        }

        /* ==================== 响应式设计 ==================== */
        @media (min-width: 768px) {
            .protagonist-card {
                flex-wrap: nowrap;
            }

            .radar-container {
                width: 200px;
                height: 200px;
            }

            .battle-skills {
                grid-template-columns: repeat(6, 1fr);
            }

            .inventory-grid {
                grid-template-columns: repeat(5, 1fr);
            }
        }

        @media (max-width: 400px) {
            .battle-skills {
                grid-template-columns: repeat(2, 1fr);
            }

            .inventory-grid {
                grid-template-columns: repeat(3, 1fr);
            }

            .equip-slot {
                width: 60px;
                height: 60px;
            }
        }

        /* ==================== 加载状态 ==================== */
        .loading {
            text-align: center;
            padding: 30px;
            color: var(--ink-light);
        }

        .loading-spinner {
            width: 30px;
            height: 30px;
            border: 3px solid var(--parchment-dark);
            border-top-color: var(--border-gold);
            border-radius: 50%;
            animation: spin 1s linear infinite;
            margin: 0 auto 10px;
        }

        @keyframes spin {
            to { transform: rotate(360deg); }
        }

        /* ==================== 地图面板样式 ==================== */
        #mapPanel {
            margin-top: 12px;
        }

        #mapPanel .card-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 10px;
            padding-bottom: 8px;
            border-bottom: 2px solid var(--border-dark);
        }

        #mapPanel .section-title {
            font-size: 16px;
            font-weight: bold;
            color: var(--accent-red);
            margin: 0;
        }

        #mapPanel .header-actions {
            display: flex;
            gap: 8px;
        }

        #mapPanel .btn-action {
            background: var(--parchment-dark);
            border: 1px solid var(--border-dark);
            border-radius: 4px;
            padding: 4px 8px;
            cursor: pointer;
            font-size: 14px;
            transition: all 0.2s;
        }

        #mapPanel .btn-action:hover {
            background: var(--border-gold);
            color: white;
        }

        #mapPanel .btn-close {
            background: var(--accent-red);
            color: white;
            border: none;
            border-radius: 4px;
            width: 24px;
            height: 24px;
            cursor: pointer;
            font-size: 14px;
        }

        .map-location {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 8px 0;
            border-bottom: 1px solid var(--border-dark);
            margin-bottom: 10px;
        }

        .map-location .location-label {
            color: var(--ink-secondary);
            font-weight: bold;
        }

        .map-location .location-name {
            color: var(--ink-primary);
            font-weight: bold;
        }

        .map-mode {
            margin-left: auto;
            padding: 2px 8px;
            border-radius: 4px;
            font-size: 11px;
            background: var(--parchment-dark);
        }

        .map-mode.battle {
            background: #ffebee;
            color: #c62828;
        }

        .map-container {
            background: var(--parchment-light);
            border: 2px solid var(--border-dark);
            border-radius: 8px;
            padding: 10px;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 250px;
            overflow: hidden;
        }

        #mapSvg {
            max-width: 100%;
            height: auto;
            background: var(--parchment-card);
            border-radius: 4px;
        }

        .battle-mode #mapSvg {
            border: 2px solid var(--accent-red);
        }

        .map-legend {
            display: flex;
            gap: 15px;
            justify-content: center;
            padding: 8px;
            border-top: 1px solid var(--border-dark);
            margin-top: 10px;
        }

        .legend-item {
            display: flex;
            align-items: center;
            gap: 5px;
            font-size: 12px;
            color: var(--ink-secondary);
        }

        .dot {
            width: 12px;
            height: 12px;
            border-radius: 50%;
            border: 2px solid;
            background: transparent;
        }

        .dot.player { border-color: #2e7d32; }
        .dot.friendly { border-color: #1e3a5f; }
        .dot.enemy { border-color: #c62828; }

        .map-status {
            display: flex;
            align-items: center;
            gap: 6px;
            padding: 6px 0;
            margin-top: 8px;
            font-size: 12px;
            color: var(--ink-light);
        }

        .status-indicator {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--success);
        }

        .status-indicator.loading {
            background: var(--warning);
            animation: pulse 1s infinite;
        }

        .status-indicator.error {
            background: var(--danger);
        }

        @keyframes pulse {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.5; }
        }

        @keyframes pulse-glow {
            0%, 100% { box-shadow: 0 0 5px rgba(139, 69, 19, 0.3); }
            50% { box-shadow: 0 0 15px rgba(139, 69, 19, 0.7), 0 0 25px rgba(184, 134, 11, 0.4); }
        }

        /* ==================== 战斗地图面板样式 ==================== */
        #battleMapPanel {
            margin-bottom: 12px;
            border-color: var(--accent-red);
        }

        #battleMapPanel::before {
            border-color: #ff6b6b;
        }

        .battle-map-info {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 8px 0;
            border-bottom: 1px solid var(--accent-red);
            margin-bottom: 10px;
        }

        .battle-map-location {
            font-weight: bold;
            color: var(--ink-primary);
        }

        .battle-map-container {
            background: linear-gradient(135deg, #f0e0d0, #e8d4c4);
            border: 2px solid var(--accent-red);
            border-radius: 8px;
            padding: 10px;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 280px;
            overflow: hidden;
        }

        #battleMapSvg {
            max-width: 100%;
            height: auto;
            border-radius: 4px;
        }

        .battle-map-legend {
            display: flex;
            gap: 20px;
            justify-content: center;
            padding: 8px;
            border-top: 1px solid var(--accent-red);
            margin-top: 10px;
        }

        .battle-map-legend .legend-item {
            display: flex;
            align-items: center;
            gap: 5px;
            font-size: 12px;
            color: var(--ink-secondary);
        }

        /* 地图通用样式增强 */
        .map-container svg, .battle-map-container svg {
            filter: drop-shadow(2px 2px 4px rgba(61, 41, 20, 0.2));
        }

        /* 角色标记动画 */
        .character-marker {
            transition: transform 0.2s ease;
            transform-origin: center center;
        }

        .character-marker:hover {
            transform: scale(1.2);
            filter: drop-shadow(0 0 10px rgba(255, 215, 0, 0.8));
        }

        /* ==================== 设置面板 ==================== */
        .settings-btn {
            position: fixed;
            top: 10px;
            right: 10px;
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--border-gold), var(--border-dark));
            border: 3px solid var(--border-gold);
            color: var(--parchment-light);
            font-size: 20px;
            cursor: pointer;
            z-index: 1000;
            box-shadow: var(--shadow-medium);
            transition: all 0.3s ease;
        }

        .settings-btn:hover {
            transform: scale(1.1);
            box-shadow: 0 0 15px rgba(184, 134, 11, 0.5);
        }

        .settings-panel {
            position: fixed;
            top: 60px;
            right: 10px;
            width: 300px;
            max-height: 400px;
            overflow-y: auto;
            background: var(--parchment-card);
            border: 2px solid var(--border-dark);
            border-radius: 8px;
            box-shadow: var(--shadow-medium);
            z-index: 999;
            padding: 15px;
        }

        .settings-panel::before {
            content: '';
            position: absolute;
            top: 4px;
            left: 4px;
            right: 4px;
            bottom: 4px;
            border: 1px solid var(--border-gold);
            border-radius: 4px;
            pointer-events: none;
            opacity: 0.5;
        }

        .settings-panel h3 {
            color: var(--accent-red);
            margin-bottom: 15px;
            padding-bottom: 8px;
            border-bottom: 1px solid var(--border-dark);
            font-size: 16px;
        }

        .setting-item {
            margin-bottom: 15px;
        }

        .setting-item label {
            display: block;
            margin-bottom: 5px;
            color: var(--ink-primary);
            font-weight: bold;
            font-size: 13px;
        }

        .setting-item select,
        .setting-item input {
            width: 100%;
            padding: 8px;
            border: 1px solid var(--border-dark);
            border-radius: 4px;
            background: var(--parchment-light);
            color: var(--ink-primary);
            font-size: 13px;
            font-family: 'Microsoft YaHei', 'Segoe UI', serif;
        }

        .settings-panel button {
            width: 100%;
            padding: 10px;
            margin-top: 10px;
            background: linear-gradient(135deg, var(--border-gold), var(--border-dark));
            border: 2px solid var(--border-gold);
            border-radius: 6px;
            color: var(--parchment-light);
            font-weight: bold;
            cursor: pointer;
            font-size: 14px;
            font-family: 'Microsoft YaHei', 'Segoe UI', serif;
            transition: all 0.3s ease;
        }

        .settings-panel button:hover {
            transform: scale(1.02);
            box-shadow: 0 0 10px rgba(184, 134, 11, 0.4);
        }

        #customApiSettings {
            display: none;
        }
    </style>
</head>
<body>
    <!-- 设置设置 -->
    <button class="settings-btn" onclick="toggleSettingsPanel()" title="设置">⚙️</button>

    <!-- 设置面板 -->
    <div id="settingsPanel" class="settings-panel" style="display: none;">
        <h3>API 设置</h3>
        <div class="setting-item">
            <label>API 来源：</label>
            <select id="apiSource" onchange="onApiSourceChange()">
                <option value="database">使用数据库 API</option>
                <option value="custom">自定义 API</option>
            </select>
        </div>
        <div id="customApiSettings">
            <div class="setting-item">
                <label>API 地址：</label>
                <input type="text" id="customApiUrl" placeholder="http://localhost:5000/api/chat">
            </div>
            <div class="setting-item">
                <label>API Key：</label>
                <input type="password" id="customApiKey" placeholder="输入 API Key">
            </div>
            <div class="setting-item">
                <label>模型名称：</label>
                <input type="text" id="customModelName" placeholder="gpt-4">
            </div>
        </div>
        <h3>地图设置</h3>
        <div class="setting-item">
            <label style="display: flex; align-items: center; cursor: pointer;">
                <input type="checkbox" id="enableMapGeneration" checked style="margin-right: 8px; width: auto;">
                <span>启用 AI 地图生成</span>
            </label>
            <small style="color: #888; margin-top: 4px; display: block;">关闭后将使用默认地图，不再调用 AI 生成</small>
        </div>
        <button onclick="saveSettings()">保存设置</button>
    </div>

    <!-- 日常模式容器 -->
    <div id="normalContainer" class="main-container active">
        <!-- 主角卡片 -->
        <div class="parchment-card">
            <div class="protagonist-card">
                <div class="protagonist-info">
                    <div class="protagonist-header">
                        <div class="character-avatar" id="protagonistAvatar" title="点击上传自定义头像">
