// 从 equipmentList 派生 GameState.equipment 槽位映射
function deriveEquippedSlots() {
    GameState.equipment = {};
    let handWeaponCount = 0;

    GameState.equipmentList.forEach(item => {
        if (!item.isEquipped || !item.slot) return;

        let slot = item.slot;
        // 手部装备：第一个放左手，第二个放右手
        if (slot === '手部') {
            handWeaponCount++;
            slot = handWeaponCount === 1 ? '左手' : '右手';
        }

        // 饰品同理
        if (slot === '饰品') {
            if (!GameState.equipment['饰品1']) {
                slot = '饰品1';
            } else {
                slot = '饰品2';
            }
        }

        GameState.equipment[slot] = {
            name: item.name,
            type: item.type,
            stats: item.stats,
            effect: item.effect,
            // 保存原始 DB 槽位用于卸下时恢复
            originalSlot: item.slot
        };
    });

    // 重新计算装备加成
    GameState.equipmentBonus = GameState.calcEquipmentBonus();
    console.log('[RPG前端] 已派生装备槽位:', Object.keys(GameState.equipment));
}

// DB 槽位 → 前端槽位映射（反向查找：给定 DB 槽位，返回前端槽位名）
function dbSlotToFrontSlot(dbSlot) {
    if (dbSlot === '手部') {
        return GameState.equipment['左手'] ? '右手' : '左手';
    }
    if (dbSlot === '饰品') {
        return GameState.equipment['饰品1'] ? '饰品2' : '饰品1';
    }
    return dbSlot; // 头部/颈部/身体/腰部/腿部/足部
}

