// ==================== 装备变化处理（仅更新内存和UI） ====================
function onEquipmentChanged() {
    const p = GameState.protagonist;
    if (!p) return;

    // 重新计算装备加成
    const newBonus = GameState.calcEquipmentBonus();
    GameState.equipmentBonus = newBonus;

    // 计算新的总属性 = 基础属性 + 新加成
    const newTotalAttrs = {
        str: GameState.baseAttrs.str + newBonus.str,
        dex: GameState.baseAttrs.dex + newBonus.dex,
        con: GameState.baseAttrs.con + newBonus.con,
        int: GameState.baseAttrs.int + newBonus.int,
        wis: GameState.baseAttrs.wis + newBonus.wis,
        cha: GameState.baseAttrs.cha + newBonus.cha
    };

    // 更新主角的总属性
    p.attrs = newTotalAttrs;

    // 根据新属性重算资源上限
    const oldMaxHP = p.res.hp.max;
    const oldMaxSP = p.res.sp.max;
    const oldMaxMP = p.res.mp.max;
    const newMaxHP = GameState.calcMaxHP(newTotalAttrs.con);
    const newMaxSP = GameState.calcMaxSP(newTotalAttrs.con, newTotalAttrs.str);
    const newMaxMP = GameState.calcMaxMP(newTotalAttrs.int);
    // 按比例调整当前值（避免卸装备后当前值超过上限）
    p.res.hp.max = newMaxHP;
    p.res.hp.cur = Math.min(p.res.hp.cur, newMaxHP);
    p.res.sp.max = newMaxSP;
    p.res.sp.cur = Math.min(p.res.sp.cur, newMaxSP);
    p.res.mp.max = newMaxMP;
    p.res.mp.cur = Math.min(p.res.mp.cur, newMaxMP);

    // 更新装备哈希
    GameState.lastEquipmentHash = GameState.getEquipmentHash();

    // 标记有待确认的装备变更
    GameState.pendingEquipmentChanges = true;

    // 显示"确认变更"按钮容器
    const confirmContainer = document.getElementById('confirmEquipBtnContainer');
    if (confirmContainer) confirmContainer.style.display = 'block';

    // 刷新UI显示
    updateProtagonistDisplay();
    drawRadarChart();

    console.log('[装备系统] 装备已变更（内存），等待确认后写入数据库');
}

// ==================== 确认装备变更（写入数据库） ====================
async function confirmEquipmentChanges() {
    const api = getAutoCardAPI();
    if (!api) {
        console.warn('[装备系统] API不可用，无法确认变更');
        return false;
    }

    if (!GameState.pendingEquipmentChanges) {
        console.log('[装备系统] 没有待确认的装备变更');
        return true;
    }

    try {
        // 1. 更新装备表的 is_equipped 列
        await writeEquipmentToTable();

        // 2. 更新主角信息表的属性列
        const p = GameState.protagonist;
        if (p && p.attrs) {
            await writeAttrsToTable(p.attrs);
        }

        // 3. 强制刷新世界书
        if (api.refreshDataAndWorldbook) {
            await api.refreshDataAndWorldbook();
            console.log('[装备系统] 已触发世界书刷新');
        }

        GameState.pendingEquipmentChanges = false;

        // 隐藏"确认变更"按钮容器
        const confirmContainer = document.getElementById('confirmEquipBtnContainer');
        if (confirmContainer) confirmContainer.style.display = 'none';

        console.log('[装备系统] 装备变更已确认并写入数据库');
        return true;
    } catch (e) {
        console.error('[装备系统] 确认装备变更失败:', e);
        return false;
    }
}

// 将属性回写到主角信息表
async function writeAttrsToTable(attrs) {
    const api = getAutoCardAPI();
    if (!api) {
        console.warn('[装备系统] API不可用，无法回写属性');
        return;
    }

    try {
        // 优先使用新的 updateRow API
        if (api.updateRow) {
            const success = await api.updateRow('主角信息', 1, {
                '力量': attrs.str,
                '敏捷': attrs.dex,
                '体质': attrs.con,
                '智力': attrs.int,
                '感知': attrs.wis,
                '魅力': attrs.cha
            });

            if (success) {
                console.log('[装备系统] 属性已通过updateRow回写:', attrs);
                // 注意：不要在这里调用 refreshDataAndWorldbook()！
                // 由 writeAllToTables 统一在所有表写完后刷新，
                // 否则回调会提前覆盖内存中尚未回写的装备和背包数据
                return;
            } else {
                console.warn('[装备系统] updateRow失败，尝试使用importTableAsJson');
            }
        }

        // 回退方案：使用 importTableAsJson（全量覆盖）
        const jsonData = api.exportTableAsJson();
        if (!jsonData) {
            console.warn('[装备系统] 无法获取表格数据');
            return;
        }

        const tables = typeof jsonData === 'string' ? JSON.parse(jsonData) : jsonData;

        // 找到主角信息表
        for (const uid in tables) {
            if (tables[uid].name === '主角信息') {
                const sheet = tables[uid];
                const headers = sheet.content[0];
                const row = sheet.content[1]; // 第一行数据

                if (!row) {
                    console.warn('[装备系统] 主角信息表没有数据行');
                    return;
                }

                // 更新属性列
                const attrMap = {
                    '力量': attrs.str,
                    '敏捷': attrs.dex,
                    '体质': attrs.con,
                    '智力': attrs.int,
                    '感知': attrs.wis,
                    '魅力': attrs.cha
                };

                for (const colName in attrMap) {
                    const idx = headers.indexOf(colName);
                    if (idx !== -1 && idx < row.length) {
                        row[idx] = attrMap[colName];
                    }
                }

                // 写回数据
                const success = await api.importTableAsJson(JSON.stringify(tables));
                if (success) {
                    console.log('[装备系统] 属性已回写表格:', attrs);
                } else {
                    console.error('[装备系统] 回写属性失败');
                }
                return;
            }
        }

        console.warn('[装备系统] 未找到主角信息表');
    } catch (e) {
        console.error('[装备系统] 回写属性表格失败:', e);
    }
}

// 将装备变更回写到主角装备表（仅更新 is_equipped 列）
