// 将背包回写到背包物品表（简化版，只写4列）
async function writeInventoryToTable() {
    const api = getAutoCardAPI();
    if (!api) return;

    try {
        if (!api.updateRow || !api.insertRow || !api.deleteRow) {
            console.warn('[装备系统] API不完整，无法回写背包');
            return;
        }

        // 获取当前背包表数据
        const jsonData = api.exportTableAsJson();
        const tables = typeof jsonData === 'string' ? JSON.parse(jsonData) : jsonData;

        let invTable = null;
        for (const uid in tables) {
            if (tables[uid].name === '背包物品表') {
                invTable = tables[uid];
                break;
            }
        }

        // 删除现有行
        if (invTable && invTable.content.length > 1) {
            const dataRows = invTable.content.slice(1);
            for (let i = dataRows.length - 1; i >= 0; i--) {
                const rowId = dataRows[i][0];
                if (rowId === null || rowId === undefined) continue;
                try {
                    await api.deleteRow({
                        tableName: '背包物品表',
                        rowIndex: rowId,
                        skipNotify: true
                    });
                } catch (e) {
                    console.warn('[装备系统] 删除背包行失败, rowId:', rowId, e);
                }
            }
        }

        // 插入当前背包物品（只写4列：物品名称、数量、描述/效果、类别）
        for (const item of GameState.inventory) {
            if (item.count > 0) {
                try {
                    await api.insertRow({
                        tableName: '背包物品表',
                        data: {
                            '物品名称': item.name,
                            '数量': item.count,
                            '描述/效果': item.desc || '',
                            '类别': item.category || '杂物'
                        },
                        skipNotify: true
                    });
                } catch (e) {
                    console.warn('[装备系统] 插入背包行失败:', item.name, e);
                }
            }
        }

        console.log('[装备系统] 背包已回写数据库');
    } catch (e) {
        console.error('[装备系统] 回写背包表格失败:', e);
    }
}

