/**
 * 清空所有战场地图缓存
 */
async function clearAllBattleMapCache() {
    if (confirm('确定要清空所有战场地图缓存吗？这将清除所有战场的缓存数据。')) {
        // 获取所有缓存键
        const keys = Object.keys(MapCache.data);
        let cleared = 0;

        for (const key of keys) {
            // 清除所有缓存（战斗和日常都清除）
            await MapCache.clearLocation(key);
            cleared++;
        }

        // 清除当前状态
        MapState.svgTemplate = '';

        const svgElement = document.getElementById('battleMapSvg');
        if (svgElement) {
            svgElement.outerHTML = '<svg id="battleMapSvg" viewBox="0 0 400 300" xmlns="http://www.w3.org/2000/svg"><text x="200" y="150" text-anchor="middle" fill="#8b0000" font-size="14">所有战场缓存已清空</text></svg>';
        }

        setMapStatus('', `已清空 ${cleared} 个缓存`);
        console.log('[地图系统] 所有战场缓存已清空');
    }
}

